{
  "openapi": "3.1.0",
  "info": {
    "description": "The atlas single-binary HTTP API: deploy BPMN models, run instances, and inspect live runtime state. This surface is unauthenticated by design — put auth in front before exposing it publicly (see ADR-0016).",
    "title": "Atlas HTTP API",
    "version": "0.8.0-dev"
  },
  "paths": {
    "/api/v1/ad/mock-directory": {
      "get": {
        "description": "Requires the `admin` role when authentication is on.",
        "operationId": "get_ad_mock-directory",
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "properties": {
                    "workers": {
                      "items": {
                        "type": "object"
                      },
                      "type": "array"
                    }
                  },
                  "type": "object"
                }
              }
            },
            "description": "OK"
          },
          "default": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            },
            "description": "Error"
          }
        },
        "summary": "Show the mock Active Directories this server's workers hold — one forest per LDAP URL, with what a mockup run put in them",
        "tags": [
          "Workers"
        ]
      },
      "post": {
        "description": "Requires the `operator` role when authentication is on.",
        "operationId": "post_ad_mock-directory",
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "type": "object"
              }
            }
          },
          "description": "Mock directory",
          "required": true
        },
        "responses": {
          "204": {
            "description": "No Content"
          },
          "default": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            },
            "description": "Error"
          }
        },
        "summary": "Report a mock directory (used by an AD worker running in mockup mode)",
        "tags": [
          "Workers"
        ]
      }
    },
    "/api/v1/api-tokens": {
      "get": {
        "description": "Requires the `admin` role when authentication is on.",
        "operationId": "get_api-tokens",
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "items": {
                    "type": "object"
                  },
                  "type": "array"
                }
              }
            },
            "description": "OK"
          },
          "default": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            },
            "description": "Error"
          }
        },
        "summary": "List API tokens by identity, scope, lifetime and provenance; secrets are not stored and never returned (admin-only, ADR-0194)",
        "tags": [
          "API tokens"
        ]
      },
      "post": {
        "description": "Requires the `admin` role when authentication is on.",
        "operationId": "post_api-tokens",
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "properties": {
                  "expiresInDays": {
                    "type": "integer"
                  },
                  "name": {
                    "type": "string"
                  },
                  "reach": {
                    "items": {
                      "type": "object"
                    },
                    "type": "array"
                  },
                  "scope": {
                    "type": "string"
                  }
                },
                "required": [
                  "name",
                  "scope"
                ],
                "type": "object"
              }
            }
          },
          "description": "Token name, scope (full, worker, metrics, status, directory, inventory, landscape or events), as reach the projects a landscape token may see (required) or the catalogues whose products an events token reads (optional; none reads the whole feed), and lifetime in days (0 = never expires). A token carries its minter's non-admin roles, except an events token, which carries feedreader and nothing else",
          "required": true
        },
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "type": "object"
                }
              }
            },
            "description": "OK"
          },
          "default": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            },
            "description": "Error"
          }
        },
        "summary": "Mint an API token for a machine — a worker on another host, a stdio MCP adapter, a CI job. The secret is returned once and never again; the scope bounds what it may reach and the lifetime when it stops working (admin-only, ADR-0194)",
        "tags": [
          "API tokens"
        ]
      }
    }
  }
}

