  "jsonrpc": "2.0",
  "id": 2,
  "result": {
    "tools": [
      {
        "description": "Get live engine counts: active process instances and active element instances (tokens).",
        "inputSchema": {
          "properties": {},
          "type": "object"
        },
        "name": "atlas_stats"
      },
      {
        "description": "List all deployed process definitions with their key, process id, version, and deploy time.",
        "inputSchema": {
          "properties": {},
          "type": "object"
        },
        "name": "atlas_list_processes"
      },
      {
        "description": "Start a new instance of a deployed process definition by its key and run it until the engine goes idle. Optionally seed the instance scope with start variables (the same {name: value} shape a human's start form submits). Returns the resulting live instance counts.",
        "inputSchema": {
          "properties": {
            "key": {
              "description": "The process definition key to instantiate.",
              "type": "integer"
            },
            "variables": {
              "description": "Optional start variables to seed the instance scope, e.g. {\"amount\": 42}. Omit for none.",
              "type": "object"
            }
          },
          "required": [
            "key"
          ],
          "type": "object"
        },
        "name": "atlas_create_instance"
      }
    ]
  }
